    seen is used. A file and a directory that collide this way are an error.
"""

import functools
import os
import re


# packignore's "**" never spans more than this many path segments.
_MAX_GLOBSTAR = 3


class PackignoreError(Exception):
    """The tree cannot be processed (packignore reports an internal error)."""


class _Rule:
    __slots__ = ("negate", "dir_only", "anchored", "segments", "specificity", "_regexes")

    def __init__(self, negate, dir_only, anchored, body):
        self.negate = negate
        self.dir_only = dir_only
        self.anchored = anchored
        self.segments = tuple(body.split("/")) if anchored else (body,)
        self.specificity = sum(1 for c in body if c not in "*?/")
        self._regexes = tuple(None if s == "**" and anchored else _segment_regex(s)
                              for s in self.segments)

    def matches(self, parts, is_dir):
        """Does this rule match the path `parts`, relative to its .packignore?"""
        if self.dir_only and not is_dir:
            return False
        if not self.anchored:
            return self._regexes[0].fullmatch(parts[-1]) is not None
        return _match_segments(self._regexes, 0, tuple(parts), 0)


@functools.lru_cache(maxsize=None)
def _segment_regex(segment):
    out = []
    for c in segment:
        if c == "*":
            if not out or out[-1] != "[^/]*":
                out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(c))
    return re.compile("".join(out), re.DOTALL)


def _match_segments(regexes, i, parts, j):
    while i < len(regexes):
        rx = regexes[i]
        if rx is None:  # "**": zero to _MAX_GLOBSTAR segments
            last = min(len(parts), j + _MAX_GLOBSTAR)
            return any(_match_segments(regexes, i + 1, parts, k) for k in range(j, last + 1))
        if j >= len(parts) or rx.fullmatch(parts[j]) is None:
            return False
        i += 1
        j += 1
    return j == len(parts)


def _parse(data):
    rules = []
    for line in data.decode("utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        negate = line.startswith("!")
        if negate:
            line = line[1:]
        dir_only = line.endswith("/")
        line = line.rstrip("/")
        anchored = "/" in line
        line = line.lstrip("/")
        if not line:
            continue
        rules.append(_Rule(negate, dir_only, anchored, line))
    return rules


class _Dir:
    __slots__ = ("name", "dirs", "files", "packignore")

    def __init__(self, name):
        self.name = name
        self.dirs = {}  # casefolded name -> _Dir
        self.files = {}  # casefolded name -> [canonical name, full path of last copy]
        self.packignore = None  # full path of the .packignore whose content counts


def _scan(root):
    """Build the tree packignore sees: regular files only, names merged case-insensitively."""
    top = _Dir("")
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            parts = os.path.relpath(full, root).replace(os.sep, "/").split("/")
            node = top
            for part in parts[:-1]:
                key = part.casefold()
                if key in node.files:
                    raise PackignoreError(f"{full}: file and directory names collide")
                node = node.dirs.setdefault(key, _Dir(part))
            key = parts[-1].casefold()
            if key in node.dirs:
                raise PackignoreError(f"{full}: file and directory names collide")
            entry = node.files.setdefault(key, [parts[-1], full])
            entry[1] = full
    return top


def _verdict(parts, is_dir, sources, inherited):
    for depth, rules in reversed(sources):
        rel = parts[depth:]
        best = None
        for index, rule in enumerate(rules):
            if rule.matches(rel, is_dir):
                if best is None or (rule.specificity, index) >= (best[0].specificity, best[1]):
                    best = (rule, index)
        if best is not None:
            return not best[0].negate
    return inherited


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    out = []

    def visit(node, parts, excluded, sources):
        if not excluded:
            entry = node.files.get(".packignore")
            if entry is not None and entry[0] == ".packignore":
                with open(entry[1], "rb") as f:
                    rules = _parse(f.read())
                if rules:
                    sources = sources + [(len(parts), rules)]
        for name, _ in node.files.values():
            path = parts + [name]
            if _verdict(path, False, sources, excluded):
                out.append("/".join(path))
        for child in node.dirs.values():
            path = parts + [child.name]
            visit(child, path, _verdict(path, True, sources, excluded), sources)

    visit(_scan(root), [], False, [])
    # packignore prints one path per line; names containing line breaks come
    # out split, exactly as its output was always read.
    return sorted(line for line in "\n".join(out).splitlines() if line)

